public enum BlendMode: Equatable, Hashable {
    
    case normal
    case screen
    case darken
    case lighten
    case overlay
    case hardLight
    case softLight
    case linearBurn
    case colorBurn
    case colorDodge
    case multiply





}

#if compiler(>=6)
extension BlendMode: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlendMode: FfiConverterRustBuffer {
    typealias SwiftType = BlendMode

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlendMode {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .normal
        
        case 2: return .screen
        
        case 3: return .darken
        
        case 4: return .lighten
        
        case 5: return .overlay
        
        case 6: return .hardLight
        
        case 7: return .softLight
        
        case 8: return .linearBurn
        
        case 9: return .colorBurn
        
        case 10: return .colorDodge
        
        case 11: return .multiply
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BlendMode, into buf: inout [UInt8]) {
        switch value {
        
        
        case .normal:
            writeInt(&buf, Int32(1))
        
        
        case .screen:
            writeInt(&buf, Int32(2))
        
        
        case .darken:
            writeInt(&buf, Int32(3))
        
        
        case .lighten:
            writeInt(&buf, Int32(4))
        
        
        case .overlay:
            writeInt(&buf, Int32(5))
        
        
        case .hardLight:
            writeInt(&buf, Int32(6))
        
        
        case .softLight:
            writeInt(&buf, Int32(7))
        
        
        case .linearBurn:
            writeInt(&buf, Int32(8))
        
        
        case .colorBurn:
            writeInt(&buf, Int32(9))
        
        
        case .colorDodge:
            writeInt(&buf, Int32(10))
        
        
        case .multiply:
            writeInt(&buf, Int32(11))
        
        }
    }
}


