/**
 * Every failure, flat on the other side: each case carries its localized text as `message` (Swift
 * `CoreError.ProjectOpen(message:)`, C# `CoreException.ProjectOpen` with `.Message`), design decision 4.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The project is open in CapCut, which would overwrite our changes when it saves.
     */
    case ProjectOpen(message: String)
    
    /**
     * The project keeps a single timeline (an older CapCut), so a dubbed timeline can't be added.
     */
    case NoTimelineList(message: String)
    
    /**
     * No such project or timeline (the `ecc info` arguments).
     */
    case NotFound(message: String)
    
    /**
     * A draft that can't be read or parsed.
     */
    case Unreadable(message: String)
    
    /**
     * A draft whose JSON is broken or lacks what a writer needs.
     */
    case Malformed(message: String)
    
    case Io(message: String)
    
    /**
     * A Rust panic caught at the boundary, with its message.
     */
    case Internal(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .ProjectOpen(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .NoTimelineList(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .Unreadable(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Malformed(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .Io(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .Internal(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .ProjectOpen(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .NoTimelineList(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .NotFound(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .Unreadable(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Malformed(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .Io(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .Internal(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))

        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreError_lift(_ buf: RustBuffer) throws -> CoreError {
    return try FfiConverterTypeCoreError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
