/**
 * What a visual layer shows. Compound clips hold their inner timeline as another `Timeline` object.
 */

public enum VisualContent {
    
    case video(path: String
    )
    case photo(path: String
    )
    case text(spec: TextLayerSpec
    )
    case compound(timeline: Timeline
    )
    case sticker(spec: StickerSpec
    )





}

#if compiler(>=6)
extension VisualContent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVisualContent: FfiConverterRustBuffer {
    typealias SwiftType = VisualContent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VisualContent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .video(path: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .photo(path: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .text(spec: try FfiConverterTypeTextLayerSpec.read(from: &buf)
        )
        
        case 4: return .compound(timeline: try FfiConverterTypeTimeline.read(from: &buf)
        )
        
        case 5: return .sticker(spec: try FfiConverterTypeStickerSpec.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VisualContent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .video(path):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .photo(path):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .text(spec):
            writeInt(&buf, Int32(3))
            FfiConverterTypeTextLayerSpec.write(spec, into: &buf)
            
        
        case let .compound(timeline):
            writeInt(&buf, Int32(4))
            FfiConverterTypeTimeline.write(timeline, into: &buf)
            
        
        case let .sticker(spec):
            writeInt(&buf, Int32(5))
            FfiConverterTypeStickerSpec.write(spec, into: &buf)
            
        }
    }
}


